import React, { useState, useEffect } from "react";
import { useParams } from "react-router-dom";
import "./DetailsProduct.scss";

const DetailsProduct = () => {
  const { productId } = useParams();
  const [product, setProduct] = useState(null);

  useEffect(() => {
    fetch("/data/product.json") // Simulação de um JSON local
      .then((response) => response.json())
      .then((data) => {
        const selectedProduct = data.find((p) => p.referenceId === productId);
        setProduct(selectedProduct);
      })
      .catch((error) => console.error("Erro ao carregar o produto:", error));
  }, [productId]);

  if (!product) return <p>Carregando...</p>;

  return (
    <div className="details-product">
      <div className="product-gallery">
        {product.imageUrl.map((image, index) => (
          <img key={index} src={image} alt={`Produto ${index + 1}`} />
        ))}
      </div>

      <div className="product-info">
        <h1>{product.productName}</h1>
        <p className="price">{product.installments}x de R$ {product.priceParcelado.toFixed(2)}</p>
        <button className="add-to-cart">ADICIONAR À SACOLA</button>
      </div>
    </div>
  );
};

export default DetailsProduct;
